import 'curriculum_models.dart';

class CourseTerm {
  const CourseTerm(this.word, this.romaji, this.meaning);
  final String word;
  final String romaji;
  final String meaning;
}

class CourseExample {
  const CourseExample(this.japanese, this.romaji, this.meaning, this.use);
  final String japanese;
  final String romaji;
  final String meaning;
  final String use;
}

class CourseSubchapter {
  const CourseSubchapter({required this.number, required this.title, required this.body, required this.examples});
  final String number;
  final String title;
  final String body;
  final List<CourseExample> examples;
}

class CourseChapter {
  const CourseChapter({required this.title, required this.summary, required this.grammar, required this.terms, required this.examples, required this.subchapters, required this.imageUrl, required this.imageLabel});
  final String title;
  final String summary;
  final List<String> grammar;
  final List<CourseTerm> terms;
  final List<CourseExample> examples;
  final List<CourseSubchapter> subchapters;
  final String imageUrl;
  final String imageLabel;
}

