    CourseChapter(title:'Menghubungkan Kalimat & Bentuk て',summary:'Memakai bentuk て secara lebih produktif untuk urutan, keadaan, permintaan, dan kegiatan sedang berlangsung.',grammar:['Vて、V','Vています','Vてから','Vてもいい','Vてはいけない'],terms:[CourseTerm('続ける','tsuzukeru','melanjutkan'),CourseTerm('始める','hajimeru','memulai'),CourseTerm('終わる','owaru','selesai'),CourseTerm('持つ','motsu','membawa/memegang'),CourseTerm('使う','tsukau','menggunakan'),CourseTerm('作る','tsukuru','membuat'),CourseTerm('洗う','arau','mencuci'),CourseTerm('着る','kiru','memakai'),CourseTerm('住む','sumu','tinggal'),CourseTerm('働く','hataraku','bekerja')],examples:[CourseExample('朝ごはんを 食べて、会社へ 行きます。','Asagohan o tabete, kaisha e ikimasu.','Sarapan lalu pergi ke kantor.','Urutan kegiatan.'),CourseExample('今、本を 読んでいます。','Ima, hon o yonde imasu.','Sekarang sedang membaca buku.','Sedang berlangsung.'),CourseExample('仕事が 終わってから、帰ります。','Shigoto ga owatte kara, kaerimasu.','Setelah pekerjaan selesai, saya pulang.','Urutan dengan てから.')],subchapters:[CourseSubchapter(number:'1.1',title:'Urutan kegiatan',body:'Gunakan て untuk menyusun beberapa aksi.',examples:[CourseExample('顔を 洗って、朝ごはんを 食べます。','Kao o aratte, asagohan o tabemasu.','Cuci muka lalu sarapan.','Urutan natural.')]),CourseSubchapter(number:'1.2',title:'Sedang berlangsung',body:'Bedakan kebiasaan bentuk ます dengan keadaan sedang berjalan.',examples:[CourseExample('電話で 話しています。','Denwa de hanashite imasu.','Sedang berbicara lewat telepon.','Progressive.')]),CourseSubchapter(number:'1.3',title:'Setelah ...',body:'Vてから menekankan aksi kedua setelah aksi pertama selesai.',examples:[CourseExample('宿題を してから、ゲームを します。','Shukudai o shite kara, geemu o shimasu.','Setelah mengerjakan PR, saya bermain game.','Urutan.')]),CourseSubchapter(number:'1.4',title:'Izin & aturan',body:'Perkuat pola izin/larangan dalam situasi nyata.',examples:[CourseExample('ここで 使っても いいですか。','Koko de tsukatte mo ii desu ka.','Boleh menggunakan di sini?','Izin.')]),CourseSubchapter(number:'1.5',title:'Review',body:'Gabungkan empat pola dalam rutinitas.',examples:[CourseExample('今、勉強しています。','Ima, benkyou shite imasu.','Sekarang sedang belajar.','Progressive.')])],imageUrl:n4Image,imageLabel:'Irodori Elementary 1 — ilustrasi konteks kehidupan sehari-hari'),
    CourseChapter(title:'Bentuk Biasa & Masa Lalu',summary:'Berpindah dari bentuk sopan ke bentuk biasa untuk percakapan, catatan, dan klausa.',grammar:['Vる/Vない','Vた/Vなかった','Adj普通形','Nだった/Nじゃなかった'],terms:[CourseTerm('思う','omou','berpikir'),CourseTerm('知る','shiru','mengetahui'),CourseTerm('分かる','wakaru','mengerti'),CourseTerm('住む','sumu','tinggal'),CourseTerm('行った','itta','telah pergi'),CourseTerm('見た','mita','telah melihat'),CourseTerm('食べない','tabenai','tidak makan'),CourseTerm('忙しい','isogashii','sibuk')],examples:[CourseExample('昨日、映画を 見た。','Kinou, eiga o mita.','Kemarin menonton film.','Bentuk biasa lampau.'),CourseExample('明日、学校へ 行かない。','Ashita, gakkou e ikanai.','Besok tidak pergi sekolah.','Bentuk biasa negatif.'),CourseExample('昨日は 暇だった。','Kinou wa hima datta.','Kemarin senggang.','Noun/na-adj past.')],subchapters:[CourseSubchapter(number:'2.1',title:'Present biasa',body:'Gunakan bentuk kamus dalam percakapan informal.',examples:[CourseExample('明日 行く。','Ashita iku.','Besok pergi.','Biasa.')]),CourseSubchapter(number:'2.2',title:'Negatif biasa',body:'Bentuk ない untuk menyatakan tidak melakukan.',examples:[CourseExample('今日は 行かない。','Kyou wa ikanai.','Hari ini tidak pergi.','Negatif.')]),CourseSubchapter(number:'2.3',title:'Past biasa',body:'Latih Vた dan でした/だった.',examples:[CourseExample('昨日、勉強した。','Kinou, benkyou shita.','Kemarin belajar.','Past.')]),CourseSubchapter(number:'2.4',title:'Past negatif',body:'Menyatakan sesuatu tidak terjadi di masa lalu.',examples:[CourseExample('昨日は 忙しくなかった。','Kinou wa isogashikunakatta.','Kemarin tidak sibuk.','i-adjective past negative.')]),CourseSubchapter(number:'2.5',title:'Kapan dipakai',body:'Bandingkan register sopan dan biasa.',examples:[CourseExample('行きます。/ 行く。','Ikimasu. / Iku.','Pergi.','Sopan vs biasa.')])],imageUrl:n4Image,imageLabel:'Irodori Elementary 1 — percakapan dan konteks informal'),
    CourseChapter(title:'Pengalaman & Pernah Melakukan',summary:'Menceritakan pengalaman, kejadian yang pernah dilakukan, dan daftar aktivitas masa lalu.',grammar:['Vたことがあります','Vたり Vたりします','ことがあります','まだ/もう pengantar'],terms:[CourseTerm('経験','keiken','pengalaman'),CourseTerm('旅行','ryokou','perjalanan'),CourseTerm('登る','noboru','mendaki'),CourseTerm('泳ぐ','oyogu','berenang'),CourseTerm('行ったことがある','itta koto ga aru','pernah pergi'),CourseTerm('食べたことがある','tabeta koto ga aru','pernah makan'),CourseTerm('見学','kengaku','kunjungan belajar')],examples:[CourseExample('日本へ 行ったことがあります。','Nihon e itta koto ga arimasu.','Saya pernah pergi ke Jepang.','Pengalaman.'),CourseExample('京都で お寺を 見たり、写真を 撮ったりしました。','Kyouto de otera o mitari, shashin o tottari shimashita.','Di Kyoto saya melihat kuil dan mengambil foto, dll.','Daftar aktivitas.')],subchapters:[CourseSubchapter(number:'3.1',title:'Pernah',body:'Vたことがあります untuk pengalaman setidaknya sekali.',examples:[CourseExample('富士山に 登ったことがあります。','Fujisan ni nobotta koto ga arimasu.','Pernah mendaki Gunung Fuji.','Pengalaman.')]),CourseSubchapter(number:'3.2',title:'Menyebut beberapa aktivitas',body:'Vたり Vたり untuk contoh kegiatan, bukan daftar lengkap.',examples:[CourseExample('映画を 見たり、本を 読んだりします。','Eiga o mitari, hon o yondari shimasu.','Saya menonton film, membaca buku, dan sebagainya.','Contoh kegiatan.')]),CourseSubchapter(number:'3.3',title:'Belum/pernah',body:'Bandingkan pengalaman yang sudah pernah dan yang belum.',examples:[CourseExample('まだ 行ったことがありません。','Mada itta koto ga arimasen.','Belum pernah pergi.','Negatif pengalaman.')]),CourseSubchapter(number:'3.4',title:'Percakapan pengalaman',body:'Tanya pengalaman orang lain.',examples:[CourseExample('日本料理を 食べたことがありますか。','Nihon ryouri o tabeta koto ga arimasu ka.','Pernah makan masakan Jepang?','Question pengalaman.')]),CourseSubchapter(number:'3.5',title:'Review',body:'Ceritakan tiga pengalaman dan satu yang belum pernah.',examples:[CourseExample('海外へ 行ったことが あります。','Kaigai e itta koto ga arimasu.','Pernah ke luar negeri.','Produksi.')])],imageUrl:n4Image,imageLabel:'Irodori Elementary 1 — perjalanan dan pengalaman'),
    CourseChapter(title:'Keinginan, Kemampuan & Tujuan',summary:'Menyatakan keinginan, kemampuan, tujuan melakukan sesuatu, dan alasan memilih aktivitas.',grammar:['Vたいです','Vことができます','Nができます','V-stemに行く','Nのために pengantar'],terms:[CourseTerm('できる','dekiru','bisa'),CourseTerm('ほしい','hoshii','ingin'),CourseTerm('行きたい','ikitai','ingin pergi'),CourseTerm('見たい','mitai','ingin melihat'),CourseTerm('買いたい','kaitai','ingin membeli'),CourseTerm('勉強する','benkyou suru','belajar'),CourseTerm('練習する','renshuu suru','berlatih')],examples:[CourseExample('日本へ 行きたいです。','Nihon e ikitai desu.','Saya ingin pergi ke Jepang.','Keinginan.'),CourseExample('漢字を 読むことが できます。','Kanji o yomu koto ga dekimasu.','Bisa membaca kanji.','Kemampuan.'),CourseExample('映画を 見に 行きます。','Eiga o mi ni ikimasu.','Pergi untuk menonton film.','Tujuan.')],subchapters:[CourseSubchapter(number:'4.1',title:'Vたい',body:'Ubah stem ます ke bentuk たい untuk keinginan.',examples:[CourseExample('日本料理を 食べたいです。','Nihon ryouri o tabetai desu.','Saya ingin makan masakan Jepang.','Keinginan.')]),CourseSubchapter(number:'4.2',title:'Vことができます',body:'Menyatakan kemampuan secara eksplisit.',examples:[CourseExample('日本語で 話すことが できます。','Nihongo de hanasu koto ga dekimasu.','Bisa berbicara dalam bahasa Jepang.','Kemampuan.')]),CourseSubchapter(number:'4.3',title:'Tujuan pergi',body:'Stem + に行く untuk tujuan melakukan aksi.',examples:[CourseExample('本を 買いに 行きます。','Hon o kai ni ikimasu.','Pergi untuk membeli buku.','Purpose.')]),CourseSubchapter(number:'4.4',title:'Keinginan vs kemampuan',body:'Bedakan “ingin” dan “bisa”.',examples:[CourseExample('泳ぎたいです。','Oyogitai desu.','Saya ingin berenang.','Keinginan.'),CourseExample('泳ぐことが できます。','Oyogu koto ga dekimasu.','Saya bisa berenang.','Kemampuan.')]),CourseSubchapter(number:'4.5',title:'Review',body:'Buat rencana akhir pekan dengan satu keinginan dan satu tujuan.',examples:[CourseExample('映画を 見に 行きたいです。','Eiga o mi ni ikitai desu.','Saya ingin pergi menonton film.','Gabungan keinginan + tujuan.'