    CourseChapter(title:'Memberi, Menerima & Bantuan',summary:'Mengungkapkan siapa memberi apa kepada siapa dan siapa membantu siapa dengan struktur yang tepat.',grammar:['あげます','もらいます','くれます','Vてあげます','Vてもらいます'],terms:[CourseTerm('あげる','ageru','memberi'),CourseTerm('もらう','morau','menerima'),CourseTerm('くれる','kureru','memberi kepada saya/kelompok saya'),CourseTerm('貸す','kasu','meminjamkan'),CourseTerm('借りる','kariru','meminjam'),CourseTerm('教える','oshieru','mengajar/memberi tahu'),CourseTerm('習う','narau','belajar dari seseorang'),CourseTerm('手伝う','tetsudau','membantu')],examples:[CourseExample('友だちに 本を あげました。','Tomodachi ni hon o agemashita.','Saya memberi buku kepada teman.','Pemberi → penerima.'),CourseExample('先生に 日本語を 教えてもらいました。','Sensei ni Nihongo o oshiete moraimashita.','Saya diajari bahasa Jepang oleh guru.','Menerima bantuan.'),CourseExample('友だちが 手伝ってくれました。','Tomodachi ga tetsudatte kuremashita.','Teman membantu saya.','Kebaikan untuk pembicara.')],subchapters:[CourseSubchapter(number:'5.1',title:'Ageru',body:'Fokus pada arah memberi keluar dari pembicara.',examples:[CourseExample('妹に お菓子を あげました。','Imouto ni okashi o agemashita.','Saya memberi makanan ringan kepada adik.','Memberi.')]),CourseSubchapter(number:'5.2',title:'Morau',body:'Fokus pada penerima yang mendapatkan sesuatu.',examples:[CourseExample('友だちから 本を もらいました。','Tomodachi kara hon o moraimashita.','Saya menerima buku dari teman.','Menerima.')]),CourseSubchapter(number:'5.3',title:'Kureru',body:'Pemberi melakukan sesuatu untuk pembicara/kelompok pembicara.',examples:[CourseExample('母が 料理を 作ってくれました。','Haha ga ryouri o tsukutte kuremashita.','Ibu membuatkan makanan untuk saya.','Benefaktif.')]),CourseSubchapter(number:'5.4',title:'Vてもらう',body:'Menekankan bahwa pembicara menerima bantuan.',examples:[CourseExample('先生に 教えてもらいました。','Sensei ni oshiete moraimashita.','Saya diajari oleh guru.','Menerima tindakan.')]),CourseSubchapter(number:'5.5',title:'Review',body:'Buat tiga kalimat memberi/menerima dan