    CourseChapter(title:'Perbandingan & Alasan',summary:'Membandingkan dua hal, menyatakan pilihan, memberi alasan, dan mengekspresikan perubahan sederhana.',grammar:['AよりBのほうが','AとBとどちら','一番','N/Adj + から','～くなる/～になる pengantar'],terms:[CourseTerm('より','yori','daripada'),CourseTerm('ほう','hou','sisi/pilihan'),CourseTerm('一番','ichiban','paling'),CourseTerm('同じ','onaji','sama'),CourseTerm('便利','benri','praktis'),CourseTerm('簡単','kantan','mudah'),CourseTerm('難しい','muzukashii','sulit'),CourseTerm('速い','hayai','cepat'),CourseTerm('遅い','osoi','lambat')],examples:[CourseExample('電車より バスのほうが 安いです。','Densha yori basu no hou ga yasui desu.','Bus lebih murah daripada kereta.','Perbandingan.'),CourseExample('夏と冬と どちらが 好きですか。','Natsu to fuyu to dochira ga suki desu ka.','Lebih suka musim panas atau dingin?','Memilih dua.'),CourseExample('日本語は おもしろいですから、勉強します。','Nihongo wa omoshiroi desu kara, benkyou shimasu.','Karena bahasa Jepang menarik, saya belajar.','Alasan.')],subchapters:[CourseSubchapter(number:'6.1',title:'Lebih ... daripada',body:'Gunakan より dan ほうが untuk membandingkan.',examples:[CourseExample('車より 電車のほうが 便利です。','Kuruma yori densha no hou ga benri desu.','Kereta lebih praktis daripada mobil.','Perbandingan.')]),CourseSubchapter(number:'6.2',title:'Memilih dua',body:'Tanya preferensi antara dua pilihan.',examples:[CourseExample('コーヒーと お茶と どちらが 好きですか。','Koohii to ocha to dochira ga suki desu ka.','Lebih suka kopi atau teh?','Pilihan dua.')]),CourseSubchapter(number:'6.3',title:'Paling',body:'Gunakan 一番 dalam kelompok.',examples:[CourseExample('この 店が 一番 安いです。','Kono mise ga ichiban yasui desu.','Toko ini paling murah.','Superlatif.')]),CourseSubchapter(number:'6.4',title:'Alasan',body:'Gunakan から untuk alasan langsung.',examples:[CourseExample('今日は 雨ですから、出かけません。','Kyou wa ame desu kara, dekakemasen.','Karena hari ini hujan, saya tidak keluar.','Sebab-akibat.')]),CourseSubchapter(number:'6.5',title:'Review',body:'Bandingkan dua cara transportasi dan jelaskan pilihanmu.',examples:[CourseExample('電車のほうが 速いですから、電車で 行きます。','Densha no hou ga hayai desu kara, densha de ikimasu.','Karena kereta lebih cepat, saya pergi naik kereta.','Perbandingan + alasan.')])],imageUrl:n4Image,imageLabel:'Irodori Elementary 1 — pilihan, tempat, dan kehidupan sehari-hari'),
    CourseChapter(title:'Rencana & Masa Depan Dekat',summary:'Menyatakan jadwal, niat, rencana, undangan, dan keputusan.',grammar:['Vつもりです','V予定です','Vませんか','Vましょう','まだ/もう'],terms:[CourseTerm('予定','yotei','rencana/jadwal'),CourseTerm('つもり','tsumori','niat'),CourseTerm('約束','yakusoku','janji'),CourseTerm('予約','yoyaku','reservasi'),CourseTerm('準備','junbi','persiapan'),CourseTerm('決める','kimeru','memutuskan'),CourseTerm('参加する','sanka suru','berpartisipasi')],examples:[CourseExample('来月 日本へ 行くつもりです。','Raigetsu Nihon e iku tsumori desu.','Bulan depan saya berniat pergi ke Jepang.','Niat.'),CourseExample('土曜日に 友だちと 会う予定です。','Doyoubi ni tomodachi to au yotei desu.','Sabtu saya berencana bertemu teman.','Jadwal.'),CourseExample('いっしょに 勉強しませんか。','Issho ni benkyou shimasen ka.','Mau belajar bersama?','Undangan.')],subchapters:[CourseSubchapter(number:'7.1',title:'Niat',body:'Gunakan つもり untuk rencana personal.',examples:[CourseExample('今年、日本語を もっと 勉強するつもりです。','Kotoshi, Nihongo o motto benkyou suru tsumori desu.','Tahun ini saya berniat belajar bahasa Jepang lebih banyak.','Niat.')]),CourseSubchapter(number:'7.2',title:'Jadwal',body:'Gunakan 予定 untuk kegiatan yang sudah direncanakan.',examples:[CourseExample('来週、旅行する予定です。','Raishuu, ryokou suru yotei desu.','Minggu depan ada rencana bepergian.','Rencana.')]),CourseSubchapter(number:'7.3',title:'Undangan',body:'Gunakan ませんか dan respon penerimaan/penolakan.',examples:[CourseExample('映画を 見ませんか。','Eiga o mimasen ka.','Mau menonton film?','Undangan.')]),CourseSubchapter(number:'7.4',title:'Persiapan',body:'Tambahkan kosakata persiapan dan reservasi.',examples:[CourseExample('ホテルを 予約しました。','Hoteru o yoyaku shimashita.','Saya sudah memesan hotel.','Reservasi.')]),CourseSubchapter(number:'7.5',title:'Review',body:'Susun rencana akhir pekan dalam empat kalimat.',examples:[CourseExample('土曜日は 友だちに 会う予定です。','Doyoubi wa tomodachi ni au yotei desu.','Sabtu saya berencana bertemu teman.','Rencana.')])],imageUrl:n4Image,imageLabel:'Irodori Elementary 1 — rencana dan aktivitas sosial'),
    CourseChapter(title:'Kondisi, Cuaca & Kesehatan',summary:'Mendeskripsikan kondisi fisik, cuaca, kesehatan, gejala sederhana, dan respons.',grammar:['どうしたんですか pengantar','～ています keadaan','～ので pengantar','Adjくて/で','Nが あります'],terms:[CourseTerm('天気','tenki','cuaca'),CourseTerm('晴れ','hare','cerah'),CourseTerm('雨','ame','hujan'),CourseTerm('雪','yuki','salju'),CourseTerm('風','kaze','angin'),CourseTerm('熱','netsu','demam'),CourseTerm('痛い','itai','sakit'),CourseTerm('元気','genki','sehat/bersemangat'),CourseTerm('薬','kusuri','obat'),CourseTerm('病院','byouin','rumah sakit')],examples:[CourseExample('今日は 雨が 降っています。','Kyou wa ame ga futte imasu.','Hari ini sedang hujan.','Keadaan berlangsung.'),CourseExample('頭が 痛いです。','Atama ga itai desu.','Kepala saya sakit.','Keluhan sederhana.'),CourseExample('薬を 飲んで、休んでください。','Kusuri o nonde, yasunde kudasai.','Minumlah obat dan istirahat.','Saran/instruksi.')],subchapters:[CourseSubchapter(number:'8.1',title:'Cuaca',body:'Bangun kosakata cuaca dan perubahan dasar.',examples:[CourseExample('今日は 晴れです。','Kyou wa hare desu.','Hari ini cerah.','Cuaca.')]),CourseSubchapter(number:'8.2',title:'Gejala',body:'Nyatakan bagian tubuh yang sakit dan kondisi.',examples:[CourseExample('おなかが 痛いです。','Onaka ga itai desu.','Perut saya sakit.','Gejala.')]),CourseSubchapter(number:'8.3',title:'Saran sederhana',body:'Gunakan permintaan sopan untuk perawatan.',examples:[CourseExample('病院へ 行ってください。','Byouin e itte kudasai.','Tolong pergi ke rumah sakit.','Saran/instruksi.')]),CourseSubchapter(number:'8.4',title:'Keadaan sedang',body:'Gunakan ています untuk kondisi yang sedang terjadi.',examples:[CourseExample('雨が 降っています。','Ame ga futte imasu.','Sedang turun hujan.','Keadaan.')]),CourseSubchapter(number:'8.5',title:'Review kesehatan',body:'Lakukan dialog pasien sederhana.',examples:[CourseExample('どうしたんですか。頭が 痛いです。','Dou shitan desu ka. Atama ga itai desu.','Ada apa? Kepala saya sakit.','Dialog kondisi.')])],imageUrl:n4Image,imageLabel:'Irodori Elementary 1 — kehidupan sehari-hari dan kesehatan'),
    CourseChapter(title:'Membaca Informasi & Instruksi',summary:'Membaca pengumuman pendek, jadwal, instruksi, formulir, dan informasi praktis.',grammar:['Nがあります','Vてください','～なければなりません pengantar','～ないでください','Klausa sederhana'],terms:[CourseTerm('案内','annai','panduan/informasi'),CourseTerm('入口','iriguchi','pintu masuk'),CourseTerm('出口','deguchi','pintu keluar'),CourseTerm('受付','uketsuke','resepsionis/penerimaan'),CourseTerm('注意','chuui','perhatian'),CourseTerm('禁止','kinshi','dilarang'),CourseTerm('無料','muryou','gratis'),CourseTerm('有料','yuuryou','berbayar'),CourseTerm('必要','hitsuyou','perlu'),CourseTerm('営業時間','eigyou jikan','jam operasional')],examples:[CourseExample('ここは 入口です。','Koko wa iriguchi desu.','Ini pintu masuk.','Membaca label tempat.'),CourseExample('受付で 名前を 書いてください。','Uketsuke de namae o kaite kudasai.','Tolong tulis nama di resepsionis.','Instruksi.'),CourseExample('ここでは 写真を 撮らないでください。','Koko dewa shashin o toranaide kudasai.','Tolong jangan memotret di sini.','Larangan sopan.')],subchapters:[CourseSubchapter(number:'9.1',title:'Tanda tempat',body:'Kenali kosakata masuk, keluar, resepsionis, dan perhatian.',examples:[CourseExample('出口は あちらです。','Deguchi wa achira desu.','Pintu keluar di sana.','Informasi arah.')]),CourseSubchapter(number:'9.2',title:'Instruksi',body:'Baca perintah pendek dengan てください.',examples:[CourseExample('こちらで 待ってください。','Kochira de matte kudasai.','Tolong tunggu di sini.','Instruksi.')]),CourseSubchapter(number:'9.3',title:'Larangan',body:'Gunakan ないでください untuk larangan sopan.',examples:[CourseExample('ここで 食べないでください。','Koko de tabenaide kudasai.','Tolong jangan makan di sini.','Larangan.')]),CourseSubchapter(number:'9.4',title:'Informasi praktis',body:'Baca harga, jam buka, gratis/berbayar, dan kebutuhan.',examples:[CourseExample('入場は 無料です。','Nyuujou wa muryou desu.','Masuknya gratis.','Informasi harga.')]),CourseSubchapter(number:'9.5',title:'Review membaca',body:'Cari kata kunci sebelum menerjemahkan keseluruhan teks.',examples:[Co